+namespace {
+int hex_value(char c) {
+    if (c >= '0' && c <= '9') {
+        return c - '0';
+    }
+    if (c >= 'a' && c <= 'f') {
+        return c - 'a' + 10;
+    }
+    if (c >= 'A' && c <= 'F') {
+        return c - 'A' + 10;
+    }
+    return -1;
+}
+
+std::string url_decode(std::string_view value) {
+    std::string decoded;
+    decoded.reserve(value.size());
+
+    for (size_t i = 0; i < value.size(); ++i) {
+        if (value[i] == '+') {
+            decoded.push_back(' ');
+            continue;
+        }
+
+        if (value[i] == '%' && i + 2 < value.size()) {
+            int high = hex_value(value[i + 1]);
+            int low = hex_value(value[i + 2]);
+            if (high != -1 && low != -1) {
+                decoded.push_back(static_cast<char>(high * 16 + low));
+                i += 2;
+                continue;
+            }
+        }
+
+        decoded.push_back(value[i]);
+    }
+
+    return decoded;
+}
+}  // namespace
+
+QueryFields parse_form(std::string_view body) {
+    QueryFields fields;
+
+    size_t start = 0;
+    while (start < body.size()) {
+        size_t end = body.find('&', start);
+        if (end == std::string_view::npos) {
+            end = body.size();
+        }
+
+        std::string_view part = body.substr(start, end - start);
+        size_t eq = part.find('=');
+
+        std::string key = url_decode(part.substr(0, eq));
+        std::string value;
+        if (eq != std::string_view::npos) {
+            value = url_decode(part.substr(eq + 1));
+        }
+
+        if (!key.empty()) {
+            fields[std::move(key)] = std::move(value);
+        }
+
+        start = end + 1;
+    }
+
+    return fields;
+}
